"""Metric layer (R5, R7).

Token level: one pooled (micro) ranking over every test token of every test
document -- this is what the authors' eval.py does:
    token_roc_auc = roc_auc_score(z_test, scores)
    precision, recall, _ = precision_recall_curve(z_test, scores); token_pr_auc = auc(recall, precision)
Document level: aggregate the token scores of a document (paper Eq. 3 = mean;
the released eval.py uses max -- both are reported).
"""

import numpy as np
from sklearn.metrics import (auc, average_precision_score, precision_recall_curve,
                             roc_auc_score)


def token_metrics(y_true, scores):
    y_true = np.asarray(y_true, dtype=int)
    scores = np.asarray(scores, dtype=float)
    precision, recall, _ = precision_recall_curve(y_true, scores)
    return {
        "token_roc_auc": float(roc_auc_score(y_true, scores)),
        "token_pr_auc": float(auc(recall, precision)),            # authors' definition
        "token_ap": float(average_precision_score(y_true, scores)),  # sklearn step version
        "n_tokens": int(len(y_true)),
        "n_pos_tokens": int(y_true.sum()),
    }


def document_scores(scores, lengths, how="mean"):
    """Split the flat token-score vector back into documents and aggregate (Eq. 3)."""
    scores = np.asarray(scores, dtype=float)
    out, start = [], 0
    for L in lengths:
        seg = scores[start:start + L]
        start += L
        if seg.size == 0:
            raise RuntimeError("empty document")
        out.append(float(seg.mean()) if how == "mean" else float(seg.max()))
    return np.asarray(out)


def document_metrics(y_doc, doc_scores):
    precision, recall, _ = precision_recall_curve(np.asarray(y_doc, dtype=int), doc_scores)
    return {
        "doc_roc_auc": float(roc_auc_score(y_doc, doc_scores)),
        "doc_pr_auc": float(auc(recall, precision)),
        "n_docs": int(len(y_doc)),
        "n_pos_docs": int(np.sum(y_doc)),
    }


def random_control(y_true, n, seed=0):
    rng = np.random.default_rng(seed)
    return token_metrics(y_true, rng.random(n))

